import sys

def solve():
    try:
        input_data = sys.stdin.read().strip()
        if not input_data:
            return
        X = int(input_data)

        n = 1
        fact = 1
        while fact < X:
            n += 1
            fact *= n

        print(n)
    except ValueError:
        pass

if __name__ == '__main__':
    solve()
